  if (u.pathname === "/api/filinglens" && req.method === "GET") { try { return fetch("https://portfolio-risk-app-production.up.railway.app"+u.pathname+u.search,{headers:{"accept":"application/json"},signal:AbortSignal.timeout(65000)}); } catch(e){ return Response.json({error:"FilingLens backend unavailable"},{status:503,headers}); } }
